//! Auto-generated -- walks `<project>/scripts/*.rs` and emits a
//! `scripts.rs` file in `OUT_DIR` that the host's `main.rs` includes.
//!
//! The dev-facing rule for an Ocarina project is: scripts live in
//! `<project>/scripts/`. Each `.rs` becomes a top-level module of
//! the host binary, so its `#[derive(OcarinaScript)]` derive runs at
//! link time and its inventory submission lights up.

use std::env;
use std::fs;
use std::io::Write;
use std::path::PathBuf;

fn main() {
    // Project root: env > compile-time fallback. CLI passes
    // OCARINA_PROJECT when invoking cargo; running the built binary
    // directly falls back to `<host>/../..` (host lives at
    // `<project>/.ocarina/host/`).
    let project = env::var("OCARINA_PROJECT")
        .map(PathBuf::from)
        .unwrap_or_else(|_| {
            PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap())
                .parent()
                .unwrap()
                .parent()
                .unwrap()
                .to_path_buf()
        });
    let scripts_dir = project.join("scripts");
    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
    let dest = out_dir.join("scripts.rs");

    println!("cargo:rerun-if-env-changed=OCARINA_PROJECT");
    println!("cargo:rerun-if-changed={}", scripts_dir.display());

    let mut out = fs::File::create(&dest).expect("create scripts.rs");
    writeln!(out, "// Generated by build.rs from <project>/scripts/*.rs").unwrap();

    if !scripts_dir.is_dir() {
        return;
    }

    let mut entries: Vec<PathBuf> = fs::read_dir(&scripts_dir)
        .expect("read scripts dir")
        .flatten()
        .map(|e| e.path())
        .filter(|p| {
            p.is_file() && p.extension().and_then(|s| s.to_str()) == Some("rs")
        })
        .collect();
    entries.sort();

    for path in entries {
        println!("cargo:rerun-if-changed={}", path.display());
        let stem = path
            .file_stem()
            .and_then(|s| s.to_str())
            .expect("script filename should be UTF-8")
            .to_string();
        if !is_ident(&stem) {
            panic!(
                "script `{}` stem must be a Rust identifier (ASCII letters / \
                 digits / `_`); rename it.",
                path.display()
            );
        }
        let abs = path.canonicalize().unwrap_or_else(|_| path.clone());
        writeln!(out, "#[path = {:?}]", abs.display().to_string()).unwrap();
        writeln!(out, "pub mod {stem};").unwrap();
    }
}

fn is_ident(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}
